import {KINDS} from '../core/rules.mjs';
import {ACCOUNT_KINDS,kindWarning} from '../core/model.mjs';
import {esc,field,select,check} from './format.mjs';
import {byGroup,tone,nextColor,COLOR_OPTIONS} from './people.mjs';

// Stammdaten: Personen, Depots, Wertpapiere. Ein Eintrag mit Vorgängen lässt
// sich ändern, aber nicht löschen. open: aufgeklappte Blöcke (bleiben nach dem Speichern, wie sie waren).
export function masterHTML(s,{editing=null,open=null}={}){
 const edit=(collection)=>editing?.collection===collection?s[collection].find(x=>x.id===editing.id)||{}:{};
 const buttons=(collection,id)=>`<button class="link" data-action="edit-record" data-collection="${collection}" data-id="${esc(id)}">ändern</button> <button class="link danger" data-action="delete-record" data-collection="${collection}" data-id="${esc(id)}">löschen</button>`;
 const form=(collection,record,inner,label)=>`<form data-form="${collection}" ${record.id?`data-id="${esc(record.id)}"`:''}><div class="grid">${inner}</div><div class="actions">${record.id?'<button type="button" class="button" data-action="cancel-edit">Abbrechen</button>':'<span></span>'}<button class="button primary">${record.id?'Änderung speichern':label}</button></div></form>`;
 const p=edit('persons'),d=edit('depots'),x=edit('securities'),a=edit('accounts'),g=edit('personGroups');
 // Personen: ohne Gruppen die einfache Liste wie bisher; mit Gruppen je Gruppe eine Zeile mit Farbpunkt, darunter ihre Personen.
 const groups=s.personGroups||[];
 const personRow=(q,group)=>`<tr><td>${groups.length?`<span class="dot${tone(group)}"></span>`:''}${esc(q.name)}</td><td class="num">${s.depots.filter(z=>z.personId===q.id).length} Depots</td><td class="num">${buttons('persons',q.id)}</td></tr>`;
 const groupRow=y=>y.group?`<tr class="group-row"><th colspan="2"><span class="dot${tone(y.group)}"></span>${esc(y.group.name)}<span class="count">${y.persons.length} ${y.persons.length===1?'Person':'Personen'}</span></th><td class="num">${buttons('personGroups',y.group.id)}</td></tr>`:'<tr class="group-row"><th colspan="3"><span class="dot"></span>Ohne Gruppe</th></tr>';
 const personRows=groups.length?byGroup(s,{empty:true}).map(y=>groupRow(y)+y.persons.map(q=>personRow(q,y.group)).join('')).join(''):s.persons.map(q=>personRow(q,null)).join('');
 const groupForm=`<details class="fold" data-keep="gruppen"${g.id||open?.get('gruppen')?' open':''}><summary><h3>Gruppen</h3><small>freiwillig – ordnet viele Personen, zum Beispiel nach Haushalt</small></summary>${form('personGroups',g,`${field('name','Name der Gruppe',g.name,'required maxlength="40"')}${select('color','Farbe',COLOR_OPTIONS,g.color||nextColor(s))}`,'Gruppe anlegen')}</details>`;
 const persons=`<section class="card"><h2>Personen</h2><table class="list"><tbody>${personRows||'<tr><td class="muted">Noch keine Personen.</td></tr>'}</tbody></table>
  ${form('persons',p,`${field('name','Name',p.name,'required maxlength="80"')}${groups.length?select('groupId','Gruppe',[['','– keine –'],...groups.map(q=>[q.id,q.name])],p.groupId||''):''}`,'Person anlegen')}${groupForm}</section>`;
 const depots=`<section class="card"><h2>Depots</h2><table class="list"><tbody>${s.depots.map(q=>`<tr><td>${esc(q.name)}<small>${esc(s.persons.find(z=>z.id===q.personId)?.name)} · ${esc(q.bank)}${q.abroad?' · ausländisch':''}${q.account?' · Konto '+esc(q.account):''}</small></td><td class="num">${s.events.filter(e=>e.depotId===q.id).length} Vorgänge</td><td class="num">${buttons('depots',q.id)}</td></tr>`).join('')||'<tr><td class="muted">Noch keine Depots.</td></tr>'}</tbody></table>
  ${s.persons.length?form('depots',d,`${select('personId','Inhaber',s.persons.map(q=>[q.id,q.name]),d.personId)}${field('name','Bezeichnung',d.name,'required maxlength="80"')}${field('bank','Bank',d.bank,'required maxlength="80"')}${field('account','Sachkonto der Buchhaltung',d.account,'maxlength="20"','Zum Beispiel 530 – für den Abgleich im Jahresblatt.')}${check('abroad','Ausländische Bank – kein deutscher Steuerabzug',d.abroad)}`,'Depot anlegen'):'<p class="muted">Zuerst eine Person anlegen.</p>'}</section>`;
 const warn=q=>{const w=kindWarning(q);return w?`<small class="warn">${esc(w)}</small>`:'';};
 const securities=`<section class="card"><h2>Wertpapiere</h2><table class="list"><tbody>${s.securities.map(q=>`<tr><td>${esc(q.name)}<small>${esc(q.isin||'ohne ISIN')} · ${esc(KINDS[q.kind])}</small>${warn(q)}</td><td class="num">${buttons('securities',q.id)}</td></tr>`).join('')||'<tr><td class="muted">Noch keine Wertpapiere.</td></tr>'}</tbody></table>
  ${form('securities',x,`${field('name','Name',x.name,'required maxlength="100"')}${field('isin','ISIN',x.isin,'maxlength="12"')}${select('kind','Art',Object.entries(KINDS),x.kind||'equityFund')}`,'Wertpapier anlegen')}
  <p class="hint">Die Art bestimmt die Teilfreistellung: Aktienfonds 30 %, Mischfonds 15 %, Immobilienfonds 60 %, Auslands-Immobilienfonds 80 %, sonstige Fonds, Aktien, Anleihen und ETCs 0 %. Den Satz nennt die Abrechnung der Bank. ETFs sind Fonds, keine Aktien. „ETC mit Rohstoffanspruch“ nur, wenn die Emissionsbedingungen nahezu vollständige Anlage im Rohstoff und ausschließlich einen Anspruch auf dessen Lieferung oder Verkaufserlös vorsehen, wie bei Xetra-Gold: dann gilt § 23 EStG mit der Jahresfrist. Andere ETCs, Anleihen und Zertifikate sind „Anleihe / Zertifikat“: ohne Teilfreistellung, im allgemeinen Verlusttopf. Derivate über den Vorgang „Sonstiger Ertrag“. Die Art nur ändern, wenn sie falsch erfasst ist: Wechselt ein Fonds tatsächlich seine Art, gilt er als verkauft und neu angeschafft (§ 22 InvStG) – das bildet Depotklar nur bei einer Verschmelzung ab.</p></section>`;
 const depotName=id=>{const q=s.depots.find(z=>z.id===id);return q?`${q.name} · ${s.persons.find(z=>z.id===q.personId)?.name||''}`:'';};
 const used=id=>s.events.filter(e=>e.accountId===id||e.toAccountId===id||e.fx?.accountId===id).length;
 // Ein Währungskonto gehört zu einem Depot oder steht für sich – dann mit eigener Bank.
 const accountWhere=q=>q.depotId?depotName(q.depotId):`${s.persons.find(z=>z.id===q.personId)?.name||''} · eigenes Konto · ${q.bank||'Bank offen'}${q.abroad?' · ausländisch':''}`;
 const owners=[...s.persons.map(p=>[`person:${p.id}`,`${p.name} – eigenes Konto ohne Depot`]),...s.depots.map(q=>[`depot:${q.id}`,`Depot ${depotName(q.id)}`])];
 const ownerOf=a.depotId?`depot:${a.depotId}`:a.personId?`person:${a.personId}`:s.depots[0]?`depot:${s.depots[0].id}`:`person:${s.persons[0]?.id||''}`;
 const accounts=`<section class="card"><h2>Währungskonten</h2><table class="list"><tbody>${(s.accounts||[]).map(q=>`<tr><td>${esc(q.name)}<small>${esc(q.currency)} · ${esc(accountWhere(q))} · ${esc(ACCOUNT_KINDS[q.kind])}${q.vatBook?' · Buchhaltung zum USt-Kurs':''}</small></td><td class="num">${used(q.id)} Buchungen</td><td class="num">${buttons('accounts',q.id)}</td></tr>`).join('')||'<tr><td class="muted">Noch keine Währungskonten.</td></tr>'}</tbody></table>
  ${s.persons.length?form('accounts',a,`${select('owner','Gehört zu',owners,ownerOf)}${field('name','Bezeichnung',a.name,'required maxlength="80" placeholder="z. B. USD-Konto"')}${field('currency','Währung',a.currency||'USD','required maxlength="3" pattern="[A-Za-z]{3}"')}${select('kind','Kontoart',Object.entries(ACCOUNT_KINDS),a.kind||'payment')}${field('bank','Bank (bei eigenem Konto)',a.depotId?'':a.bank,'maxlength="80"','Bei einem Depot gelten dessen Bank und Inhaber.')}${check('abroad','Ausländische Bank – kein deutscher Steuerabzug',!a.depotId&&a.abroad)}${select('bookRate','Kurs für die Buchhaltung',[['','Tageskurs'],['vat','Umsatzsteuer-Umrechnungskurs (Monatskurs)']],a.vatBook?'vat':'')}`,'Währungskonto anlegen'):'<p class="muted">Zuerst eine Person anlegen.</p>'}
  <p class="hint">Die Kontoart entscheidet über die Steuer auf Währungsgewinne: verzinste Konten nach § 20 EStG ohne Haltefrist, unverzinste und reine Zahlungsverkehrskonten nach § 23 EStG mit einem Jahr Frist (BMF vom 19.05.2022, Rz. 131). Ein Konto braucht kein Depot: ohne Depot gehört es einer Person und trägt seine eigene Bank. Währung, Kontoart, Depot und Inhaber bleiben fest, sobald Buchungen bestehen.</p>
  <p class="hint">Mit „Umsatzsteuer-Umrechnungskurs“ zeigt das Konto zusätzlich ein Blatt, in dem jede Bewegung zum Monatskurs des BMF umgerechnet ist. Die Steuer rechnet weiter mit dem Tageskurs, denn § 20 Abs. 4 S. 1 EStG verlangt den Kurs im Zeitpunkt des Geschäfts. Die Wahl lässt sich jederzeit ändern, an den erfassten Beträgen ändert sich nichts. Die Kurse stehen unter „Kurse“.</p></section>`;
 return `<div class="page-head"><div><h1>Stammdaten</h1><p>Wer hält was wo. Wertpapiere lassen sich auch direkt beim Erfassen eines Vorgangs anlegen.</p></div></div><div class="columns">${persons}${depots}${securities}${accounts}</div>`;
}
